function repairPriceSearch() {
    if (!document.body.classList.contains('page-id-2903')) return;

    if (typeof window.g_ucDynamicFilters === 'undefined') {
      window.g_ucDynamicFilters = { runWithTrashold: function () {} };
    }

    var input = document.querySelector('.uc-search-filter__input');
    var items = Array.prototype.slice.call(document.querySelectorAll('.ue-grid-item'))
      .filter(function (item) { return /Записаться/i.test(item.innerText || ''); });

    if (!input || !items.length || input.dataset.yaclinicPriceFix) return;
    input.dataset.yaclinicPriceFix = '1';

    var wrapper = input.closest('.uc-search-filter-input-wrapper') || input.parentElement;
    var status = document.createElement('div');
    status.className = 'yaclinic-search-status';
    status.setAttribute('role', 'status');
    status.setAttribute('aria-live', 'polite');
    wrapper.insertAdjacentElement('afterend', status);

    function applyFilter() {
      var query = normalize(input.value);
      var count = 0;

      items.forEach(function (item) {
        var matches = !query || normalize(item.innerText).includes(query);
        item.classList.toggle('yaclinic-price-hidden', !matches);
        if (matches) count += 1;
      });

      if (!query) {
        status.textContent = '';
      } else if (count) {
        status.textContent = 'Найдено: ' + count;
      } else {
        status.textContent = 'Ничего не найдено. Измените запрос.';
      }
    }

    input.addEventListener('input', applyFilter);
    window.addEventListener('pageshow', applyFilter);
    window.setTimeout(applyFilter, 0);
    applyFilter();
  }

