function attachBookingObserverWhenReady() {
    var host = document.getElementById('sqns-booking-widget-root');
    if (!host || !host.shadowRoot) return false;
    observeBookingWidget();
    return true;
  }

  function attachBookingHostObserver() {
    if (!document.body || attachBookingObserverWhenReady()) return;
    var bookingHostObserver = new MutationObserver(function (_, observer) {
      if (!attachBookingObserverWhenReady()) return;
      observer.disconnect();
    });
    bookingHostObserver.observe(document.body, { childList: true, subtree: true });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', attachBookingHostObserver, { once: true });
  } else {
    attachBookingHostObserver();
  }

/* The home card uses the current published doctor, never a fixed staff ID. */
add_filter('elementor/widget/render_content', static function ($content, $widget) {
    if ('32c0db0' !== $widget->get_id() || 'doctor' !== get_post_type()) return $content;
    $doctor_id = (int) get_the_ID();
    if ($doctor_id <= 0 || 'publish' !== get_post_status($doctor_id)) return $content;
    return str_replace('data-booking-source="doctor"',
        'data-booking-source="doctor" data-doctor-id="' . $doctor_id . '"', $content);
}, 40, 2);
